package io.github.foundry4j.forge.web.file;

/// Metadata of a stored file.
///
/// Applications usually persist the [key] next to the business record and use it to
/// stream the content back later.
///
/// @param key              opaque storage key, generated by [FileStorage]
/// @param originalFilename sanitized file name supplied by the client
/// @param contentType      normalized MIME type
/// @param size             stored size in bytes
public record StoredFile(String key, String originalFilename, String contentType, long size) {
}
